CREATE OR REPLACE FUNCTION mission_factory_owner.validate_quest_draft_v2(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare q jsonb; e jsonb; ph jsonb; m jsonb; t jsonb; a jsonb; v jsonb;
        episode_keys text[]:='{}'; step_keys text[]; n integer:=0; ep text;
begin
IF p->>'schema_version'='mission-factory-draft/3' AND p->>'content_kind'='quest_human' THEN RETURN mission_factory_owner.c416_validate_human_draft_v3(p);END IF;
  if not mission_factory_owner.keys_exact_v2(p,array['schema_version','content_kind','catalog_version','npc_bindings','budget_policy_id','variants','quest'])
     or p->>'schema_version' is distinct from 'mission-factory-draft/2' or p->>'content_kind' is distinct from 'quest_ai'
     or jsonb_typeof(p->'npc_bindings')<>'array'
     or not mission_factory_owner.keys_exact_v2(p->'variants',array['ai'])
     or not mission_factory_owner.keys_exact_v2(p#>'{variants,ai}',array['state','mode','document'])
     or p#>>'{variants,ai,mode}' is distinct from 'ai'
     or coalesce(p#>>'{variants,ai,state}','') not in('missing','complete')
     or (p#>>'{variants,ai,state}'='missing' and p#>'{variants,ai,document}'<>'null'::jsonb)
     or (p#>>'{variants,ai,state}'='complete' and jsonb_typeof(p#>'{variants,ai,document}')<>'object')
     or jsonb_typeof(p->'catalog_version')<>'string'
     or jsonb_typeof(p->'budget_policy_id') not in('null','string')
  then raise exception 'MF_QUEST_DRAFT_SHAPE' using errcode='22023'; end if;
  q:=p->'quest';
  if not mission_factory_owner.keys_exact_v2(q,array['title','plot_private','quest_kind','roster_assignment_id','episodes'])
     or jsonb_typeof(q->'title')<>'string' or jsonb_typeof(q->'plot_private')<>'string'
     or coalesce(q->>'quest_kind','') not in('one_shot','trama')
     or jsonb_typeof(q->'roster_assignment_id') not in('null','string')
     or jsonb_typeof(q->'episodes')<>'array'
     or (case when jsonb_typeof(q->'episodes')='array' then jsonb_array_length(q->'episodes') else 100000 end)>32
     or (case when jsonb_typeof(p->'npc_bindings')='array' then jsonb_array_length(p->'npc_bindings') else 100000 end)>12
  then raise exception 'MF_QUEST_SOURCE_SHAPE' using errcode='22023'; end if;
  for a in select value from jsonb_array_elements(p->'npc_bindings') loop
    if not mission_factory_owner.keys_exact_v2(a,array['npc_id','npc_version_id','actor_key','phase_keys','combat','team','role','presence','reveal'])
       or coalesce(a->>'actor_key','') !~ '^[a-z][a-z0-9_]{1,63}$'
       or jsonb_typeof(a->'phase_keys')<>'array' or jsonb_typeof(a->'combat')<>'boolean'
       or coalesce(a->>'team','') not in('alleati','avversari','civili')
       or length(btrim(coalesce(a->>'role',''))) not between 1 and 80
       or a->>'presence' is distinct from 'in_scene' or a->>'reveal' is distinct from 'visible'
       or coalesce(a->>'npc_id','') !~ '^[0-9a-fA-F-]{36}$'
       or coalesce(a->>'npc_version_id','') !~ '^[0-9a-fA-F-]{36}$'
    then raise exception 'MF_QUEST_NPC_SHAPE' using errcode='22023'; end if;
  end loop;
  for e in select value from jsonb_array_elements(q->'episodes') loop
    n:=n+1;
    if not mission_factory_owner.keys_exact_v2(e,array['episode_key','ordinal','title','incipit_public','plot_private','phases','maps','npc_actor_keys','terminal_rules'])
       or coalesce(e->>'episode_key','') !~ '^[a-z][a-z0-9_]{1,63}$'
       or e->>'ordinal' is distinct from n::text or e->>'episode_key'=any(episode_keys)
       or jsonb_typeof(e->'title')<>'string' or jsonb_typeof(e->'incipit_public')<>'string'
       or jsonb_typeof(e->'plot_private')<>'string' or jsonb_typeof(e->'phases')<>'array'
       or jsonb_typeof(e->'maps')<>'array' or jsonb_typeof(e->'npc_actor_keys')<>'array'
    then raise exception 'MF_QUEST_EPISODE_SHAPE' using errcode='22023'; end if;
    ep:=e->>'episode_key'; episode_keys:=episode_keys||ep; step_keys:='{}';
    for ph in select value from jsonb_array_elements(e->'phases') loop
      perform mission_factory_owner.c360_phase_shape_v1(ph);
      if coalesce(ph->>'step_key','') !~ '^[a-z][a-z0-9_]{1,63}$'
         or ph->>'step_key'=any(step_keys)
         or jsonb_typeof(ph->'capability_key')<>'string'
         or jsonb_typeof(ph->'public_setup')<>'string'
         or jsonb_typeof(ph->'private_direction')<>'string'
         or jsonb_typeof(ph->'transition_options')<>'array'
      then raise exception 'MF_QUEST_PHASE_SHAPE' using errcode='22023'; end if;
      step_keys:=step_keys||(ph->>'step_key');
      for t in select value from jsonb_array_elements(ph->'transition_options') loop
        -- Draft/2 stays editable when a legacy terminal lacks outcome.
        -- Certification below requires the outcome and rejects it on a
        -- nonterminal route; authoring never invents a default.
        if not (mission_factory_owner.keys_exact_v2(t,array['decision_key','to_step_key'])
                or mission_factory_owner.keys_exact_v2(
                     t,array['decision_key','to_step_key','terminal_outcome']))
           or coalesce(jsonb_typeof(t->'decision_key'),'')<>'string'
           or coalesce(jsonb_typeof(t->'to_step_key'),'') not in('null','string')
           or (t ? 'terminal_outcome'
               and coalesce(jsonb_typeof(t->'terminal_outcome'),'')<>'string')
        then raise exception 'MF_QUEST_TRANSITION_SHAPE' using errcode='22023'; end if;
      end loop;
    end loop;
    for m in select value from jsonb_array_elements(e->'maps') loop
      if not mission_factory_owner.keys_exact_v2(m,array['step_key','context_media_id','arena_ref'])
         or coalesce(m->>'step_key','')<>all(step_keys)
         or jsonb_typeof(m->'context_media_id') not in('null','string')
         or jsonb_typeof(m->'arena_ref') not in('null','object')
      then raise exception 'MF_QUEST_MAP_SHAPE' using errcode='22023'; end if;
      if jsonb_typeof(m->'arena_ref')='object' and
         (not mission_factory_owner.keys_exact_v2(m->'arena_ref',array['template_key','template_version','zone_key'])
          or m#>>'{arena_ref,zone_key}' is distinct from 'arena')
      then raise exception 'MF_QUEST_ARENA_SHAPE' using errcode='22023'; end if;
    end loop;
    if not mission_factory_owner.keys_exact_v2(e->'terminal_rules',array['terminal_step_key','outcome_capability_key','reward_policy_id'])
       or jsonb_typeof(e#>'{terminal_rules,reward_policy_id}') not in('null','string')
    then raise exception 'MF_QUEST_TERMINAL_SHAPE' using errcode='22023'; end if;
  end loop;
  return p;
end $function$
